from stats import summarize_readings as s
import unittest
class T(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(s([]), (None,None,None))
        self.assertEqual(s([None,None]), (None,None,None))
    def test_immutable(self):
        a=[5,1,None,3]
        self.assertEqual(s(a),(1,5,3.0))
        self.assertEqual(a,[5,1,None,3])
    def test_neg_dec(self):
        self.assertEqual(s([-2.5,-1,0.5]),(-2.5,0.5,-1.0))
    def test_tuple_input(self):
        self.assertEqual(s((3,4,None)),(3,4,3.5))
unittest.main(verbosity=2)

